// ============================================================
//  studio/image.js — destination photos generated by Gemini
//  Own prompt (Carousel's generator stays untouched): natural,
//  documentary-style travel photography, and the client's hard rule:
//  no mosques or minarets.
// ============================================================

const config = require('../config');
const destinations = require('./destinations');

// Generic scenes (client 2026-11-21): ONE big landmark, close up, never a city seen from above.
const VARIANTS = [
  'the most famous landmark of the place, seen up close from street level',
  'the best-known historic building or monument of the place, filling the frame',
  'the iconic sight of the place from a low angle, close enough to see its details',
];

// The scene lists name times of day ("at golden hour"); the light is now always bright daylight.
const stripTimeOfDay = (s) => String(s).replace(/,?\s*(at|in)\s+(golden|blue)\s+hour|,?\s*at\s+(sunset|sunrise|dusk|dawn)|,?\s*in\s+(soft|warm)\s+[a-z -]*light|,?\s*on a clear evening/gi, '').trim();

// Poster-style prompt (client decision 2026-10-30): realistic travel photo laid out for the
// "Schlicht" story template: open sky in the top 35% (price and route), the scene in the middle,
// a calm bottom for the logo. One real viewpoint, no impossible collages (client: realism first).
// Rule for every offer kind: generate the DESTINATION, never the product itself (no invented
// hotel, room, pool, ship interior or holiday home: that would mislead the customer).
const KIND_RULES = {
  flight: 'Show the place itself; no aircraft.',
  package: 'Show the holiday destination (coast, bay, old town or landscape); NO hotel building, hotel pool, room, restaurant or resort facility that could be mistaken for the offered hotel.',
  cruise: 'Show the sea and coastline of the destination at sunset; at most one large plain white cruise ship far away, without any name, logo or company colours; never a ship interior.',
  home: 'Show the natural surroundings (lake, mountains, countryside or coast); no specific house, cabin or villa.',
};

// Variety rule (client 2026-11-21): slides of one post must not all show buildings. Each slide of
// a bundle gets its own SUBJECT and its own light, in a fixed order (deterministic, easy to check).
// A subject the city does not have is replaced by the closest real equivalent of that city.
const SHOTS = [
  { id: 'landmark', shot: 'the most famous landmark of the city, close up from street level', light: 'bright clean daylight, clear blue sky' },
  { id: 'water', shot: 'the city by the water: its harbour, port or marina with boats, or its river or lake shore (if none, its best-known fountain or pond)', light: 'warm golden hour light shortly before sunset' },
  { id: 'castle', shot: 'the best-known castle, fortress, citadel or palace of the city or right next to it (if none, its old city walls or town gate), seen whole and close, with its approach or gardens', light: 'bright daylight with a few soft white clouds' },
  { id: 'nature', shot: 'nature in or right next to the city: its best-known park, forest, gardens or lake, lush and green or in true autumn/winter colours, the city only hinted at', light: 'soft morning daylight' },
  { id: 'bridge', shot: 'the best-known bridge of the city (if none, its most famous street or gateway), seen from an angle with strong perspective', light: 'blue hour just after sunset, deep blue sky, warm lights switched on, no black night' },
  { id: 'heights', shot: 'a hill, mountain or high viewpoint of the city with people-free natural ground in the foreground and the place below and behind (not a flat aerial view)', light: 'clear afternoon light, crisp air' },
  { id: 'promenade', shot: 'the city\'s beach, corniche, riverside promenade or lakeside walk, with a few small strolling people far away', light: 'warm late-afternoon light' },
  { id: 'museum', shot: 'the exterior of the city\'s best-known museum, opera house or modern architecture icon, with its forecourt', light: 'bright daylight with strong side light' },
];
const shotOf = (i) => SHOTS[((i % SHOTS.length) + SHOTS.length) % SHOTS.length];
/** Subject ids: every subject for every city (client 2026-11-21): Gemini searches the web for
 *  real places of the city (places.js), so no hand-written lists are needed. */
const subjectIds = () => SHOTS.map((x) => x.id);

// Light, viewpoint and life vary per photo (client 2026-11-21: three bridges must not look like one
// photo). Picked from fixed lists by the number of photos the library already has for this city and
// subject, so consecutive photos always differ.
const LIGHTS = [
  'soft early-morning light, pastel sky, gentle long shadows',
  'clear midday-to-afternoon daylight, deep blue sky, crisp contrast',
  'warm golden hour light shortly before sunset, glowing warm sky',
  'blue hour just after sunset, deep blue sky, warm lights switched on, no black night',
];
// Composition techniques of great travel photography; one per photo, rotated.
const VIEWS = [
  'LAYERED DEPTH: a real foreground element sharp in the lower third, the place in the middle, sky or hills behind; the eye travels into the picture',
  'LEADING LINES: a path, railing, riverbank, bridge deck or row of trees leads the eye from the lower corner to the place',
  'FRAME IN A FRAME: the place seen through a real arch, gateway, window, branches or between two buildings',
  'REFLECTION OR SYMMETRY: the place mirrored in still water or a wet surface, or a calm symmetrical front view',
  'INTIMATE DETAIL: tight, close framing of the signature detail with the rest of the place recognisable behind it',
  'HUMAN SCALE: a small person or object gives scale to the place, rule of thirds, generous calm space around it',
];
const LIFE = [
  'no people at all, calm and pristine',
  'a few small people far away (walking, cycling), none facing the camera',
  'one element of life in the foreground: a boat, a bicycle, a cafe table or market stall (no readable text)',
];
function variation(n, seed = '') {
  const h = [...String(seed)].reduce((a, c) => (a * 31 + c.charCodeAt(0)) >>> 0, 0);
  return { light: LIGHTS[(n + h) % LIGHTS.length], view: VIEWS[(n * 2 + h) % VIEWS.length], life: LIFE[(n + (h >> 3)) % LIFE.length] };
}

/** Generic { shot, light } of a subject id (or n-th subject). */
function subjectFor(place, i) {
  const sh = typeof i === 'string' ? SHOTS.find((x) => x.id === i) || SHOTS[0] : shotOf(Number(i) || 0);
  return { id: sh.id, shot: sh.shot, light: sh.light };
}

/** One subject per slide, never the same subject twice in a post while another one is still free.
 *  `places` in slide order; the list starts at `start` so each post opens differently. */
function planSubjects(places, start = 0) {
  const order = SHOTS.map((_, k) => SHOTS[(k + start) % SHOTS.length].id);
  const used = new Set();
  return places.map((place) => {
    const ids = subjectIds(place);
    const id = order.find((x) => ids.includes(x) && !used.has(x)) || order.find((x) => ids.includes(x));
    used.add(id);
    return id;
  });
}

// Festive panorama style (client 2026-11-23, after the Fly Erbil website): the city celebrated in one
// rich, vivid picture with several of its sights, framed by a seasonal foreground. The season follows
// the travel month, so a winter post never shows autumn leaves.
const SEASONS = {
  winter: 'WINTER: the top corner and one side are framed by snow-covered fir branches with warm fairy lights; a light dusting of snow on roofs and ground; a festive Christmas-market glow where it fits; crisp clear winter sky',
  spring: 'SPRING: the top corner and one side are framed by branches full of pink and white cherry or apple blossom; fresh green trees, tulips and flower beds',
  summer: 'SUMMER: the top corner and one side are framed by lush green leaves and colourful summer flowers; deep blue sky, warm sunshine, lively outdoor life',
  autumn: 'AUTUMN: the top corner and one side are framed by branches of glowing orange, red and golden autumn leaves; golden trees along the streets and riverbanks',
};
const seasonOf = (month) => { const m = Number(String(month || '').slice(5, 7)) || (new Date().getMonth() + 1); return m === 12 || m <= 2 ? 'winter' : m <= 5 ? 'spring' : m <= 8 ? 'summer' : 'autumn'; };

function buildFestivePrompt(city, hero, kind, season) {
  return [
    `A REAL PHOTOGRAPH (not an illustration, not a painting, not a 3D render, not a cartoon) of ${city}: a vibrant, premium travel advertising photo shot on a full-frame camera.`,
    `HERO: ${String(hero).replace(/\.+$/, '')}. It fills the middle of the frame, large, sharp and exactly as it really looks; it is unmistakably the subject of the photo.`,
    `BACKGROUND: only what is really visible from this viewpoint; at most one or two other real sights of ${city} small in the distance, never a collage of the city's landmarks.`,
    'VIEWPOINT: slightly elevated (from a riverside promenade, a terrace or a hill), so the city looks rich, wide and full of life; a promenade, river or square with railings, lanterns and flowers in the lower part.',
    SEASONS[season] || SEASONS.autumn,
    'COLOURS AND LIGHT: rich, joyful colours as in a professionally edited real photo (punchy but believable); bright sunshine, deep blue sky with soft white clouds, sparkling water; real textures of stone, glass, water and snow, real proportions, natural perspective.',
    'STRICTLY NO cartoon, illustration, painting, digital art, toy-like or miniature look, no outlines, no flat colours, no exaggerated HDR, no oversized Ferris wheels or invented buildings.',
    'VERTICAL 9:16 POSTER: the seasonal frame and the sky in the top quarter stay calm enough for a price and a route written there; the bottom eighth is a little darker for a light logo; one seamless picture, no panels or borders.',
    KIND_RULES[kind] || KIND_RULES.flight,
    'MOOD: happy, inviting, premium; a few small people strolling, none facing the camera; no traffic jams, no cranes, no construction.',
    'FORBIDDEN: any mosque or minaret anywhere in the frame; any readable text: no brand names, logos, shop signs, letters, flags with writing, watermarks or frames.',
  ].join(' ');
}

// Short prompt (client 2026-11-24, tested in the session on Düsseldorf and Munich): the place by
// name, where it is seen from, the light, a dark bottom for the logo, the camera. Long rule lists
// made the photos dull or cartoonish; this short form gave real, attractive photos.
// Light mix: mostly blue hour and golden sunset, sometimes clear daylight (4 / 4 / 2 in 10).
const PHOTO_LIGHTS = {
  blue: 'Blue hour just after sunset: deep blue sky with a last pink glow on the horizon, warm lit facades, windows and street lamps.',
  golden: 'Golden-hour sunset: warm orange and pink sky with soft clouds, the scene glowing, reflections where there is water.',
  day: 'Clear sunny late afternoon: deep blue sky with a few white clouds, warm light on the facades.',
};
const LIGHT_ORDER = ['blue', 'golden', 'blue', 'golden', 'day', 'golden', 'blue', 'golden', 'blue', 'day'];
const lightKeyOf = (n) => LIGHT_ORDER[((n % 10) + 10) % 10];
const lightOf = (n) => PHOTO_LIGHTS[typeof n === 'string' && PHOTO_LIGHTS[n] ? n : lightKeyOf(Number(n) || 0)];

// Dark lower part, varied per slide (client 2026-11-24: "water and a railing" in every slide looked the same).
const GROUNDS = {
  shade: 'a shaded cobblestone or paved square in the foreground',
  trees: 'the dark shadows of trees falling across the ground in the foreground',
  grass: 'dark green grass or a shaded lawn in the foreground',
  steps: 'shaded old stone steps or a low stone wall in the foreground',
  water: 'dark calm water in the foreground',
  street: 'a quiet shaded street or pavement leading into the picture',
};
const GROUND_ORDER = Object.keys(GROUNDS);

function buildPhotoPrompt(city, place, spot, kind, n, ground) {
  return [
    `Professional travel photograph of ${city}, vertical format.`,
    `${String(place).replace(/\.+$/, '')}${spot ? ', seen ' + String(spot).replace(/^(seen\s+)?/i, '').replace(/\.+$/, '') : ''}, large in the frame.`,
    lightOf(n),
    `The lower fifth of the frame is naturally dark and calm, for a logo: ${GROUNDS[ground] || GROUNDS.shade}. No railing in the foreground unless it is really part of the place.`,
    'Shot on a Sony A7R IV, rich but natural colours, crisp detail, magazine quality.',
    kind && kind !== 'flight' ? KIND_RULES[kind] : '',
    'No text, no signs, no logos, no mosques or minarets.',
  ].filter(Boolean).join(' ');
}

// Cover of a flight post with several destinations (client 2026-11-24): an aircraft above the
// clouds, magazine style; never an airline: white plus ONE other colour, no logo, no text, different
// angles. Rotated by the number of covers already saved.
const PLANE_COLOURS = ['deep navy blue', 'warm gold', 'burgundy red', 'dark green', 'turquoise', 'graphite grey'];
const PLANE_VIEWS = [
  'side view of a modern twin-engine passenger jet cruising above a sea of clouds',
  'the jet seen from slightly below and behind, banking gently above towering clouds',
  'front three-quarter view of the jet climbing out of the clouds',
  'the jet seen from above, flying over a soft blanket of clouds',
  'rear three-quarter view of the jet heading into the horizon above the clouds',
];
const PLANE_LIGHTS = ['at golden sunset, warm orange and pink sky', 'at blue hour, deep blue sky with a last glow on the horizon', 'at sunrise, pastel pink and gold sky', 'in clear afternoon sun, deep blue sky'];
function buildTravelCoverPrompt(n) {
  const i = ((n % 60) + 60) % 60;
  return [
    `Professional aviation photograph for a travel magazine cover, vertical format: ${PLANE_VIEWS[i % PLANE_VIEWS.length]}, ${PLANE_LIGHTS[i % PLANE_LIGHTS.length]}.`,
    `Simple two-colour livery: white fuselage with ${PLANE_COLOURS[i % PLANE_COLOURS.length]} tail and engines only; no logo, no name, no letters, no registration, no flag, nothing that looks like a real airline.`,
    'The aircraft is sharp and large in the upper middle; the lower third of the frame is darker clouds, calm, for a title.',
    'Shot with a telephoto lens, rich but natural colours, crisp detail. No text anywhere.',
  ].join(' ');
}
// Cover of a package post (client 2026-11-24): the client types a keyword (e.g. "Familien",
// "Last Minute"); the photo shows a fitting holiday scene.
function buildKeywordCoverPrompt(keyword, n) {
  return [
    `Professional travel advertising photograph, vertical format, illustrating the holiday offer theme "${String(keyword).slice(0, 60)}"`,
    '(for example: "Familien" -> a happy family on a beach or by a river; "Last Minute" -> travellers with a suitcase hurrying happily towards the sea; "Wellness" -> a calm spa terrace by the sea).',
    PLANE_LIGHTS[((n % 4) + 4) % 4].replace(/^at |^in /, 'Light: ') + '.',
    'People seen from behind or from the side, small to medium in the frame, nobody looks into the camera; real and natural, not posed stock style.',
    'The lower third of the frame is naturally darker and calm, for a title. Shot on a Sony A7R IV, rich but natural colours. No text, no signs, no logos, no mosques or minarets.',
  ].join(' ');
}
async function generateTravelCover(n = 0) { return geminiImage(buildTravelCoverPrompt(n)); }
async function generateKeywordCover(keyword, n = 0) { return geminiImage(buildKeywordCoverPrompt(keyword, n)); }

function buildPrompt(city, variant, kind, sh) {
  return [
    sh
      ? `An award-winning editorial travel photograph of ${city} for the cover story of a premium travel magazine: a unique, artistic, unexpected view, not a cliché postcard.`
      : `Photorealistic travel poster photograph of ${city}. Scene: ${stripTimeOfDay(variant)}.`,
    sh
      ? `SUBJECT: ${String(sh.shot).replace(/\.+$/, "")}. It must be a REAL, recognisable place of ${city}, close enough to feel there. NOT a flat aerial view, NOT a distant skyline.` + (sh.view ? ` COMPOSITION: ${sh.view}. LIFE IN THE PICTURE: ${sh.life}. Follow the camera position and layers of the brief exactly; show the signature detail; do NOT make the cliché shot.` : '')
      : 'MOST IMPORTANT: ONE famous landmark is the hero, photographed CLOSE UP from street level or a low angle, large in the frame and full of detail; it must be instantly recognisable. NOT an aerial view, NOT a city panorama, NOT a skyline seen from far away.',
    KIND_RULES[kind] || KIND_RULES.flight,
    'REALISM: must look like a real photo by a top travel photographer (full-frame camera, the lens a master would choose for this shot, from wide angle to telephoto compression, RAW, natural colour grading); real materials, real proportions, architecturally accurate; ONE real viewpoint: only landmarks that are really visible together from one place, no collage of distant landmarks; no CGI, no illustration, no painted or plastic AI look, no HDR glow. COLOURS: natural and believable, true to the light of the scene (daylight, golden hour or blue hour must look clearly different); never neon or cartoonish.',
    'POSTER COMPOSITION (vertical 9:16): the top 15% of the frame is calm sky, because a price and a route are written there; the main subject fills most of the frame below it, tack-sharp; anything tall stays below that sky band;',
    'the bottom 15% is a little darker and calm, because a light logo is placed there; do NOT add water, a lake or trees just for that, show what is really in front of the subject.',
    'ONE SEAMLESS PHOTO: these zones are only where things sit, never separate panels; the sky is one continuous natural sky and the light changes gradually; no horizontal bands, stripes, seams, borders, collage or split-screen look.',
    sh ? `LIGHT: ${sh.light}; crisp detail, crystal-clear air, no haze; the top sky band stays calm and even so the price text reads well.` : 'LIGHT: bright, clean daylight on a sunny day (late morning to afternoon), clear blue sky, crisp detail everywhere, crystal-clear air, no haze, no dusk or night.',
    sh && sh.life ? 'MOOD: aspirational, premium and inviting; tidy scene, no traffic, no cranes, no construction, no rubbish; nobody faces the camera.' : 'MOOD: aspirational, premium and inviting; tidy scene, no traffic, no cranes, no construction, no rubbish, at most a few small distant people, none facing the camera.',
    'FORBIDDEN: any mosque or minaret anywhere in the frame; any readable text anywhere: no brand names or logos on buildings, rooftops or billboards (e.g. hotel or company signs), no shop signs, no letters, no flags with writing, no watermarks, borders or frames.',
  ].filter(Boolean).join(' ');
}

const toOffer = (o) => (typeof o === 'string' ? { to: { name: o } } : o);
const shuffle = (a) => a.map((x) => [Math.random(), x]).sort((p, q) => p[0] - q[0]).map((p) => p[1]);

/** `n` different scenes for the offer: its own scenes (destinations.js) first, then generic ones. */
function scenesFor(offer, n) {
  const own = shuffle((destinations.find(offer) || {}).ai || []);
  return [...own, ...shuffle(VARIANTS)].slice(0, n);
}

/** Returns a data URI (image) or throws. `scene` is optional (else a random one). */
async function generatePhoto(offerOrCity, scene, subject, opts = {}) {
  return (await generateSubjectPhoto(offerOrCity, scene, subject, opts)).dataUri;
}

/** Photo of a subject at a REAL place found on the web (places.js): never a place that is already
 *  in the library for this city and subject, so each new photo shows a different place.
 *  Returns { dataUri, place } (place = name, or null for a generic scene). */
async function generateSubjectPhoto(offerOrCity, scene, subject, opts = {}) {
  if (!config.GEMINI_API_KEY) throw new Error('GEMINI_API_KEY is not set');
  const offer = destinations.photoSubject(toOffer(offerOrCity));
  const city = [offer.to.name, offer.country].filter(Boolean).join(', ');
  const variant = scene || scenesFor(offer, 1)[0];
  let sh = null, found = null;
  if (subject != null) {
    sh = subjectFor(offer.to, subject);
    const lib = require('./ai-library');
    const key = lib.keyOf(offer.to);
    const exclude = [...(opts.exclude || []), ...lib.list(key, sh.id).map((x) => x.place).filter(Boolean)];
    try { found = await require('./places').pick(key || city, offer.to.name, offer.country || '', sh.id, exclude); } catch (err) { console.error('studio places:', err.message); }
    if (found) sh = { ...sh, shot: `${found.name}. ${found.view}` };
    sh = { ...sh, n: opts.light && PHOTO_LIGHTS[opts.light] ? opts.light : lib.list(key).length + (opts.offset || 0) };
  }
  const url = `https://generativelanguage.googleapis.com/v1beta/models/${config.GEMINI_IMAGE_MODEL}:generateContent`;
  const res = await fetch(url, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'x-goog-api-key': config.GEMINI_API_KEY },
    body: JSON.stringify({
      contents: [{ parts: [{ text: sh ? buildPhotoPrompt(city, found ? found.name : sh.shot, found ? found.spot : '', offer.kind, sh.n || 0, opts.ground) : buildPrompt(city, variant, offer.kind, sh) }] }],
      generationConfig: { responseModalities: ['Image'], imageConfig: { imageSize: config.GEMINI_IMAGE_SIZE || '2K', aspectRatio: '9:16' } },
    }),
    signal: AbortSignal.timeout(120000),
  });
  require('./ai-status').report(res.status);
  if (!res.ok) throw new Error(`Gemini image error ${res.status}`);
  const json = await res.json();
  const part = (json?.candidates?.[0]?.content?.parts || []).find((p) => p.inlineData || p.inline_data);
  if (!part) throw new Error('Gemini returned no image');
  const inline = part.inlineData || part.inline_data;
  return { dataUri: `data:${inline.mimeType || inline.mime_type || 'image/png'};base64,${inline.data}`, place: found ? found.name : null, light: sh ? (typeof sh.n === 'string' ? sh.n : lightKeyOf(sh.n || 0)) : null };
}

/** Three different AI photos (one per slide), generated in parallel. Fails when the first one fails;
 *  a missing slide 2/3 photo is null (that slide then uses the first photo). */
async function generateSet(offerOrCity) {
  const offer = destinations.photoSubject(toOffer(offerOrCity));
  const scenes = scenesFor(offer, 3);
  const [a, b, c] = await Promise.allSettled(scenes.map((sc) => generatePhoto(offer, sc)));
  if (a.status !== 'fulfilled') throw a.reason;
  return [a.value, b.status === 'fulfilled' ? b.value : null, c.status === 'fulfilled' ? c.value : null];
}

const ENHANCE_PROMPT = [
  'Retouch this real travel photograph like a top magazine photo editor. Keep it the SAME photo: same place, same buildings, same landscape, same viewpoint and framing; do not add, move or invent anything.',
  'Improve only: exposure and white balance, warm natural golden light, clean clear blue sky, clearer water, gentle contrast, crisp detail, slight lens-shadow correction.',
  'Remove small distractions only (litter, wires, cranes, stray signs, cars, random people) where it is easy and natural.',
  'Colours rich but true-to-life, no oversaturation, no HDR or glow, no painted or AI look. No text, logos or watermarks.',
].join(' ');

/** Magazine-style retouch of a real photo (data URI in, data URI out). Keeps the place real. */
async function enhancePhoto(dataUri) {
  if (!config.GEMINI_API_KEY) throw new Error('GEMINI_API_KEY is not set');
  const m = /^data:(image\/(?:jpeg|png|webp));base64,([A-Za-z0-9+/=]+)$/.exec(dataUri || '');
  if (!m) throw new Error('bad photo');
  const res = await fetch(`https://generativelanguage.googleapis.com/v1beta/models/${config.GEMINI_IMAGE_MODEL}:generateContent`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'x-goog-api-key': config.GEMINI_API_KEY },
    body: JSON.stringify({
      contents: [{ parts: [{ text: ENHANCE_PROMPT }, { inline_data: { mime_type: m[1], data: m[2] } }] }],
      generationConfig: { responseModalities: ['Image'], imageConfig: { imageSize: config.GEMINI_IMAGE_SIZE || '2K' } },
    }),
    signal: AbortSignal.timeout(120000),
  });
  require('./ai-status').report(res.status);
  if (!res.ok) throw new Error(`Gemini enhance error ${res.status}`);
  const json = await res.json();
  const part = (json?.candidates?.[0]?.content?.parts || []).find((p) => p.inlineData || p.inline_data);
  if (!part) throw new Error('Gemini returned no image');
  const inline = part.inlineData || part.inline_data;
  return `data:${inline.mimeType || inline.mime_type || 'image/png'};base64,${inline.data}`;
}

// Magazine cover of multi-offer posts (client decision 2026-11-04): a THEME photo (season, summer
// holiday, families ...), never one of the destinations. Kept in a small library per theme and
// season and reused, so a cover costs one generation only now and then.
const fs = require('fs');
const path = require('path');
const THEME_DIR = path.join(__dirname, '..', 'cache', 'studio-themes');
const THEME_SCENES = {
  autumn: ['a sunny autumn panorama over a European old town with trees in red and golden colours', 'a wide autumn landscape of hills and a lake with colourful trees in bright sunshine'],
  winter: ['a bright winter panorama of a snowy alpine valley with a small village under a clear blue sky', 'a sunny winter panorama of a European old town with a light dusting of snow on the roofs'],
  spring: ['a panorama of a European city with blossoming trees in the foreground in bright spring sunshine', 'green spring hills with wild flowers and a lake under a clear blue sky'],
  summer: ['a wide panorama of a turquoise Mediterranean bay with a white beach and clear water', 'a sunny summer coastline with cliffs and a calm blue sea seen from above'],
  holidays: ['a wide sunny beach panorama with a few families far away, seen from behind, no faces', 'a bright seaside promenade panorama in summer with palm trees and the sea'],
  families: ['a family of four walking along a bright sandy beach far away, seen from behind, no faces', 'a sunny lakeside meadow with a family having a picnic far in the distance, no faces'],
  city: ['a panoramic European river city skyline with bridges in bright daylight', 'an elevated panorama over the rooftops of a historic European capital on a clear day'],
  eid: ['a festive bright city square decorated with warm lanterns and string lights, no religious buildings', 'golden festive lanterns hanging over a lively street in daylight, no religious buildings'],
  newroz: ['the green spring mountains of Kurdistan with people in colourful Kurdish clothes dancing far away, bright spring day, no faces', 'a wide panorama of green Kurdish mountains with wild flowers in spring sunshine'],
  lastminute: ['a dramatic panoramic coastline with turquoise sea seen from above in bright sunshine', 'a wide panorama of a sunny island bay with boats on clear blue water'],
};
const THEMES = Object.keys(THEME_SCENES);
const SEASON_OF = ['winter', 'winter', 'spring', 'spring', 'spring', 'summer', 'summer', 'summer', 'autumn', 'autumn', 'autumn', 'winter'];
const themeOf = (theme, date = new Date()) => (THEMES.includes(theme) ? theme : SEASON_OF[date.getMonth()]); // 'auto' -> season
const pick = (a) => a[Math.floor(Math.random() * a.length)];

function buildThemePrompt(theme) {
  return [
    `Photorealistic travel magazine cover photograph: ${pick(THEME_SCENES[theme])}.`,
    'MOST IMPORTANT: a wide panoramic view in bright, clean daylight with a clear blue sky; vivid but believable colours; looks like a real photo, no CGI, no illustration, no painted look.',
    'COMPOSITION (vertical 9:16) — STRICT: the top 30% is calm sky (a magazine title is placed there); the bottom 30% is calm and a little darker (the headline is placed there).',
    'People only small and far away, seen from behind, never recognisable faces.',
    'FORBIDDEN: any mosque, minaret or other religious building; any readable text, signs, logos, flags with writing, watermarks, borders or frames.',
  ].join(' ');
}

async function geminiImage(prompt) {
  if (!config.GEMINI_API_KEY) throw new Error('GEMINI_API_KEY is not set');
  const res = await fetch(`https://generativelanguage.googleapis.com/v1beta/models/${config.GEMINI_IMAGE_MODEL}:generateContent`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'x-goog-api-key': config.GEMINI_API_KEY },
    body: JSON.stringify({
      contents: [{ parts: [{ text: prompt }] }],
      generationConfig: { responseModalities: ['Image'], imageConfig: { imageSize: config.GEMINI_IMAGE_SIZE || '2K', aspectRatio: '9:16' } },
    }),
    signal: AbortSignal.timeout(120000),
  });
  require('./ai-status').report(res.status);
  if (!res.ok) throw new Error(`Gemini image error ${res.status}`);
  const json = await res.json();
  const part = (json?.candidates?.[0]?.content?.parts || []).find((p) => p.inlineData || p.inline_data);
  if (!part) throw new Error('Gemini returned no image');
  const inline = part.inlineData || part.inline_data;
  return `data:${inline.mimeType || inline.mime_type || 'image/png'};base64,${inline.data}`;
}

const LIBRARY_SIZE = 3; // per theme: generate until three exist, then reuse them at random
/** Cover photo for a theme ('auto' = season of today). `fresh` forces a new generation. */
async function generateThemeCover(theme, fresh = false) {
  const t = themeOf(theme);
  let saved = [];
  try { saved = fs.readdirSync(THEME_DIR).filter((f) => new RegExp(`^${t}-[a-f0-9]{8}\\.txt$`).test(f)); } catch { /* none yet */ }
  if (!fresh && saved.length >= LIBRARY_SIZE) return fs.readFileSync(path.join(THEME_DIR, pick(saved)), 'utf8');
  const dataUri = await geminiImage(buildThemePrompt(t));
  fs.mkdirSync(THEME_DIR, { recursive: true });
  fs.writeFileSync(path.join(THEME_DIR, `${t}-${require('crypto').randomBytes(4).toString('hex')}.txt`), dataUri);
  return dataUri;
}

